#[inline]
unsafe fn match_row(
    mut match_1: *const match_struct,
    mut row: c_int,
    mut curr_D: *mut score_t,
    mut curr_M: *mut score_t,
    mut last_D: *const score_t,
    mut last_M: *const score_t,
) {
    let n: c_int = (*match_1).needle_len;
    let m: c_int = (*match_1).haystack_len;
    let i: c_int = row;

    let needle_ch = (*match_1).lower_needle[i as usize] as c_int;
    let lower_haystack: *const c_char =
        (&raw const (*match_1).lower_haystack) as *const c_char;
    let match_bonus: *const score_t = (&raw const (*match_1).match_bonus) as *const score_t;

    let neg_inf: score_t = -::core::f32::INFINITY as score_t;
    let gap_score: score_t = if i == n - 1 {
        SCORE_GAP_TRAILING
    } else {
        SCORE_GAP_INNER
    };

    let mut prev_score: score_t = neg_inf;
    let mut prev_M: score_t = neg_inf;
    let mut prev_D: score_t = neg_inf;

    let mut j: isize = 0;
    let m_isize = m as isize;

    while j < m_isize {
        // SAFETY: j is in 0..m, and callers provide valid arrays/buffers for all row accesses.
        let hay = unsafe { *lower_haystack.offset(j) as c_int };
        // SAFETY: j is in 0..m, and callers provide valid arrays/buffers for all row accesses.
        let last_d_j = unsafe { *last_D.offset(j) };
        // SAFETY: j is in 0..m, and callers provide valid arrays/buffers for all row accesses.
        let last_m_j = unsafe { *last_M.offset(j) };

        if needle_ch == hay {
            let score = if i == 0 {
                // SAFETY: j is in 0..m, and match_bonus has at least m initialized elements.
                unsafe { j as score_t * SCORE_GAP_LEADING + *match_bonus.offset(j) }
            } else if j != 0 {
                // SAFETY: j is in 0..m, and match_bonus has at least m initialized elements.
                let bonus = unsafe { *match_bonus.offset(j) };
                let a = prev_M + bonus;
                let b = (prev_D as c_double + 1.0f64) as score_t;
                if a > b { a } else { b }
            } else {
                neg_inf
            };

            prev_D = last_d_j;
            prev_M = last_m_j;
            // SAFETY: j is in 0..m, and callers provide valid writable buffers for curr_D/curr_M.
            unsafe { *curr_D.offset(j) = score };
            let extended = prev_score + gap_score;
            prev_score = if score > extended { score } else { extended };
            // SAFETY: j is in 0..m, and callers provide valid writable buffers for curr_D/curr_M.
            unsafe { *curr_M.offset(j) = prev_score };
        } else {
            prev_D = last_d_j;
            prev_M = last_m_j;
            // SAFETY: j is in 0..m, and callers provide valid writable buffers for curr_D/curr_M.
            unsafe { *curr_D.offset(j) = neg_inf };
            prev_score += gap_score;
            // SAFETY: j is in 0..m, and callers provide valid writable buffers for curr_D/curr_M.
            unsafe { *curr_M.offset(j) = prev_score };
        }

        j += 1;
    }
}

